-- Generated from the supplied real inputs. EC remains mS/m; missing remains NULL.
-- Execute after 10_extend_realdata_schema.sql. Unchanged snapshots are repeatable.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';
SET LOCAL standard_conforming_strings=on;
DO $$ BEGIN IF current_database()<>'dongthap_gis' THEN RAISE EXCEPTION 'Can chon dongthap_gis'; END IF; END $$;
ON CONFLICT(source_code) DO NOTHING;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.data_source WHERE (source_code='MRC_WATER_QUALITY' AND (is_demo OR source_type<>'OFFICIAL')) OR (source_code='LEGACY_MONTHLY_PIPELINE' AND (is_demo OR source_type<>'RESEARCH'))) THEN RAISE EXCEPTION 'Source code collision: different source kind'; END IF; END $$;
SELECT 'MRC_VN_019803',s.source_id,'VN','019803','Tân Châu - MRC',a.area_id FROM public.data_source s CROSS JOIN public.analysis_area a WHERE s.source_code='MRC_WATER_QUALITY' AND a.area_code='TANCHAU' ON CONFLICT(site_code) DO NOTHING;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.measurement_site m JOIN public.data_source s USING(source_id) WHERE m.site_code='MRC_VN_019803' AND m.country_code='VN' AND m.external_site_code='019803' AND s.source_code='MRC_WATER_QUALITY') THEN RAISE EXCEPTION 'Site code collision'; END IF; END $$;
SELECT 'MRC_EC_TANCHAU_bd4cf100cb4782e3',source_id,'RAW_EC','IN_SITU_OBSERVATION','Conductivity.Water Quality@VN_019803_[Tan Chau].csv','bd4cf100cb4782e37b355d94f15911c1bab2c4a9d4ad69d2fa2c3b4c5d590ba7',464,'{"unit": "mS/m", "source_timezone": "UTC+07:00", "temperature_reference": "UNKNOWN", "quality": "Preserved original O/E, approval and grade; internal quality remains UNVERIFIED", "coordinates_in_attached_export": false, "salinity_conversion_performed": false}'::jsonb
FROM public.data_source WHERE source_code='MRC_WATER_QUALITY' ON CONFLICT(sha256) DO NOTHING;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.source_dataset d JOIN public.data_source s USING(source_id) WHERE d.sha256='bd4cf100cb4782e37b355d94f15911c1bab2c4a9d4ad69d2fa2c3b4c5d590ba7' AND d.dataset_kind='RAW_EC' AND d.source_row_count=464 AND s.source_code='MRC_WATER_QUALITY') THEN RAISE EXCEPTION 'Dataset identity mismatch'; END IF; END $$;
SELECT 'MASTER_f9b2de085a265a13',source_id,'MONTHLY_FEATURES','MIXED_DERIVED','master_timeseries.csv','f9b2de085a265a13e21779aa7c95b8d0caaed9335ae61d820475f54e519eac71',1000,'{"period": "MONTH", "pipeline": "Uploaded process_data.py; snapshot retained without reconstructing absent sources", "conductivity_unit": "mS/m", "water_level_unit": "m", "water_level_vertical_datum": "UNKNOWN", "glofas_unit_from_column_name": "m3/s", "glofas_spatial_extraction": "LEGACY_SPATIAL_MEAN_UNVERIFIED", "meteo_units": "NOT_VERIFIED_FROM_RAW_API_METADATA", "windspeed_mean_semantics": "Mean of daily maximum windspeed in supplied code", "source_specific_coordinates": "NOT_PRESENT_IN_MASTER", "feature_data_kind": "Mixed observation/satellite/reanalysis/model-derived", "monthly_sample_count": "Verified separately for TanChau EC only", "operational_gate_decision_ready": false}'::jsonb
FROM public.data_source WHERE source_code='LEGACY_MONTHLY_PIPELINE' ON CONFLICT(sha256) DO NOTHING;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.source_dataset d JOIN public.data_source s USING(source_id) WHERE d.sha256='f9b2de085a265a13e21779aa7c95b8d0caaed9335ae61d820475f54e519eac71' AND d.dataset_kind='MONTHLY_FEATURES' AND d.source_row_count=1000 AND s.source_code='LEGACY_MONTHLY_PIPELINE') THEN RAISE EXCEPTION 'Dataset identity mismatch'; END IF; END $$;
CREATE TEMP TABLE tmp_v2_ec(source_row integer,observed_at timestamptz,conductivity_ms_per_m double precision,unit text,source_label text,observed_or_estimated char(1),approval_level text,grade text) ON COMMIT DROP;
SELECT d.dataset_id,d.source_id,s.site_id,t.source_row,t.observed_at,t.conductivity_ms_per_m,t.unit,t.source_label,t.observed_or_estimated,t.approval_level,t.grade FROM tmp_v2_ec t CROSS JOIN public.source_dataset d CROSS JOIN public.measurement_site s
WHERE d.sha256='bd4cf100cb4782e37b355d94f15911c1bab2c4a9d4ad69d2fa2c3b4c5d590ba7' AND s.site_code='MRC_VN_019803' ON CONFLICT(dataset_id,site_id,observed_at) DO NOTHING;
DO $$ BEGIN IF EXISTS(SELECT source_row,observed_at,conductivity_ms_per_m,unit,source_label,observed_or_estimated,approval_level,grade FROM tmp_v2_ec EXCEPT SELECT o.source_row,o.observed_at,o.conductivity_ms_per_m,o.unit,o.source_label,o.observed_or_estimated,o.approval_level,o.grade FROM public.conductivity_observation o JOIN public.source_dataset d USING(dataset_id) WHERE d.sha256='bd4cf100cb4782e37b355d94f15911c1bab2c4a9d4ad69d2fa2c3b4c5d590ba7') THEN
RAISE EXCEPTION 'Existing EC snapshot has different values; not overwritten'; END IF;
IF (SELECT count(*) FROM public.conductivity_observation o JOIN public.source_dataset d USING(dataset_id) WHERE d.sha256='bd4cf100cb4782e37b355d94f15911c1bab2c4a9d4ad69d2fa2c3b4c5d590ba7')<>464 THEN RAISE EXCEPTION 'EC snapshot row count mismatch'; END IF; END $$;
CREATE TEMP TABLE tmp_v2_monthly(area_code text,source_row integer,month_start date,conductivity_ms_per_m double precision,precipitation_sum double precision,temperature_mean double precision,temperature_max double precision,temperature_min double precision,evapotranspiration_sum double precision,windspeed_mean double precision,humidity_mean double precision,shortwave_rad_sum double precision,water_level_m double precision,glofas_discharge_m3s double precision) ON COMMIT DROP;
SELECT d.dataset_id,a.area_id,t.source_row,t.month_start,t.conductivity_ms_per_m,t.precipitation_sum,t.temperature_mean,t.temperature_max,t.temperature_min,t.evapotranspiration_sum,t.windspeed_mean,t.humidity_mean,t.shortwave_rad_sum,t.water_level_m,t.glofas_discharge_m3s FROM tmp_v2_monthly t JOIN public.analysis_area a USING(area_code) CROSS JOIN public.source_dataset d
WHERE d.sha256='f9b2de085a265a13e21779aa7c95b8d0caaed9335ae61d820475f54e519eac71' ON CONFLICT(dataset_id,area_id,month_start) DO NOTHING;
DO $$ BEGIN IF EXISTS(SELECT area_code,source_row,month_start,conductivity_ms_per_m,precipitation_sum,temperature_mean,temperature_max,temperature_min,evapotranspiration_sum,windspeed_mean,humidity_mean,shortwave_rad_sum,water_level_m,glofas_discharge_m3s FROM tmp_v2_monthly EXCEPT SELECT a.area_code,m.source_row,m.month_start,m.conductivity_ms_per_m,m.precipitation_sum,m.temperature_mean,m.temperature_max,m.temperature_min,m.evapotranspiration_sum,m.windspeed_mean,m.humidity_mean,m.shortwave_rad_sum,m.water_level_m,m.glofas_discharge_m3s FROM public.monthly_feature m JOIN public.analysis_area a USING(area_id) JOIN public.source_dataset d USING(dataset_id)
WHERE d.sha256='f9b2de085a265a13e21779aa7c95b8d0caaed9335ae61d820475f54e519eac71') THEN
RAISE EXCEPTION 'Existing monthly snapshot has different values; not overwritten'; END IF;
IF (SELECT count(*) FROM public.monthly_feature m JOIN public.source_dataset d USING(dataset_id) WHERE d.sha256='f9b2de085a265a13e21779aa7c95b8d0caaed9335ae61d820475f54e519eac71')<>1000 THEN RAISE EXCEPTION 'Monthly snapshot row count mismatch'; END IF; END $$;
COMMIT;
